UPDATE lessons SET title='Year 4, Week 2, Lesson 4: Quick check: place value and rounding', data=json_patch(data,'{"child_mission":"A quick check mixes reading, partitioning, comparing and rounding so you can spot which place-value skill still needs practice.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same method to a larger number or a new context, then compare two solution paths for accuracy.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nName the skill tested: “Which is greater, 58,090 or 58,900?”\n\nFEEDBACK\nComparing / place value (hundreds vs tens after matching higher places).\n\nWATCH FOR\nSkipping the reason on a review item hides the mistake type.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nComplete a twenty-item mixed check. Tally errors by skill (read/expand/compare/round) and write one practice goal.\n\nWrite a short reflection naming one step you corrected and why.","interactive_activities":null,"learning_area":"Mathematics","learning_intention":"A quick check mixes reading, partitioning, comparing and rounding so you can spot which place-value skill still needs practice.","lesson_number":4,"lesson_role":"Fluency and review","materials":["Paper or typed answer space","Pencil","Optional: place-value chart or number line"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["MA2-RN-01"],"parent_notes":"Parent: Marking guidance for the independent task: Complete a twenty-item mixed check. Tally errors by skill (read/expand/compare/round) and write one practice goal. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: new numbers solved with visible working for review; key places/values named. Do not award marks for retyping the model.\n\nParent: Written model 2: Sample misconception: Skipping the reason on a review item hides the mistake type.. Correction uses Comparing / place value (hundreds vs tens after matching higher places).. Why: restores accurate review.\n\nParent: Likely misconception: Skipping the reason on a review item hides the mistake type. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Solve one fresh problem that uses review with different numbers from the worked model. Show working and name the places or values that matter.\n\nParent: Short-answer focus 2: Describe one likely mistake with review, show corrected working, and say why the correction works.\n\nParent: Marking notes: Accept any mathematically valid solution that uses new numbers, shows working for review, and names places/values. Reject copied model numbers. / Accept a named misconception about review, corrected working, and a method reason. Reject vague “I was wrong” with no repair..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"This matches the taught method for review. The other choices miss a key step or use a common mistake.","options":["Comparing / place value (hundreds vs tens after matching higher places)","Skipping the reason on a review item hides the mistake type","A claim that names no evidence from the lesson material","A method that skips the key step taught in this lesson"],"question":"Name the skill tested: “Which is greater, 58,090 or 58,900?” Which response is most accurate?","type":"multiple_choice"},{"correct_index":2,"explanation":"This is the misconception to avoid for review; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["Comparing / place value (hundreds vs tens after matching higher places)","Caref